        var jobs = (await client.GetFromJsonAsync<JsonElement>("/api/jobs")).EnumerateArray().ToList();
        Assert.Equal(5, jobs.Count);
        var bySender = jobs.GroupBy(j => j.GetProperty("sender").GetString()).ToDictionary(g => g.Key!, g => g.ToList());
